The program is a greedy list scheduler. I have not compiled it or run it on any input.

1. Targets are processed in order of increasing deadline, with ties broken by larger goal points.
2. A target is skipped if its critical-path compile time alone (ignoring replication) already exceeds its deadline.
3. Otherwise every dependency that is not yet compiled is compiled first, in dependency order. Each file is placed on the server where it would finish earliest. The start time is the later of the server being free and all dependencies being available there.
4. A file counts as available on a server once it is compiled there, or once the earliest replication of any copy has arrived.
5. Steps are only ever appended to the end of a server's queue, so every dependency appears earlier in the submission, as the statement requires.
6. If every target is skipped, the program still writes one step (the first file, which has no dependencies), because the format requires E ≥ 1.

Memory is about 80 MB for the per-server finish times. The worst case is roughly 10^9 simple operations from checking every server for every file, which should fit in 10 seconds.

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int C,T,S;
    scanf("%d %d %d",&C,&T,&S);
    vector<string> names(C);
    vector<ll> c(C),r(C);
    vector<vector<int>> dep(C);
    unordered_map<string,int> id;
    id.reserve(C*2);
    char buf[64];
    for(int i=0;i<C;i++){
        ll a,b;
        scanf("%s %lld %lld",buf,&a,&b);
        names[i]=buf;c[i]=a;r[i]=b;id[names[i]]=i;
        int n;scanf("%d",&n);
        for(int j=0;j<n;j++){scanf("%s",buf);dep[i].push_back(id[buf]);}
    }
    struct Tg{int f;ll d,g;};
    vector<Tg> tg(T);
    for(int i=0;i<T;i++){
        ll d,g;scanf("%s %lld %lld",buf,&d,&g);
        tg[i]={id[buf],d,g};
    }
    sort(tg.begin(),tg.end(),[](const Tg&a,const Tg&b){
        if(a.d!=b.d)return a.d<b.d;
        return a.g>b.g;});
    const ll INF=LLONG_MAX/4;
    vector<ll> ckp(C);
    for(int i=0;i<C;i++){
        ll m=0;
        for(int d:dep[i])m=max(m,ckp[d]);
        ckp[i]=m+c[i];
    }
    vector<ll> fin((size_t)C*S,INF);
    vector<ll> minRep(C,INF);
    vector<char> done(C,0),vis(C,0);
    vector<ll> freeT(S,0);
    vector<pair<int,int>> steps;
    for(auto&t:tg){
        if(ckp[t.f]>t.d)continue;
        if(done[t.f])continue;
        vector<int> order;
        vector<pair<int,int>> st;
        vector<int> visited;
        vis[t.f]=1;visited.push_back(t.f);
        st.push_back({t.f,0});
        while(!st.empty()){
            auto &tp=st.back();
            int u=tp.first;
            if(tp.second<(int)dep[u].size()){
                int v=dep[u][tp.second++];
                if(!done[v]&&!vis[v]){
                    vis[v]=1;visited.push_back(v);
                    st.push_back({v,0});
                }
            } else {
                order.push_back(u);
                st.pop_back();
            }
        }
        for(int v:visited)vis[v]=0;
        for(int f:order){
            ll best=INF;int bs=0;
            for(int s=0;s<S;s++){
                ll start=freeT[s];
                if(start>=best)continue;
                for(int d:dep[f]){
                    ll a=min(fin[(size_t)d*S+s],minRep[d]);
                    if(a>start)start=a;
                }
                ll e=start+c[f];
                if(e<best){best=e;bs=s;}
            }
            freeT[bs]=best;
            fin[(size_t)f*S+bs]=best;
            minRep[f]=min(minRep[f],best+r[f]);
            done[f]=1;
            steps.push_back({f,bs});
        }
    }
    if(steps.empty())steps.push_back({0,0});
    printf("%d\n",(int)steps.size());
    for(auto&p:steps)printf("%s %d\n",names[p.first].c_str(),p.second);
}
